import{_ as d,a as e,c as a,ac as r}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"MySQL 基础概念对照 · MySQL至索引","description":"MySQL 事务、引擎、索引、字符集与数据类型对照。","frontmatter":{"title":"MySQL 基础概念对照 · MySQL至索引","description":"MySQL 事务、引擎、索引、字符集与数据类型对照。","splitFrom":"middleware/mysql/plus/subjects/mysql-base.md","showdocs":{"topics":[{"id":"mysql","title":"MySQL","link":"/topics/mysql/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"MySQL 基础概念对照","summary":"MySQL 事务、引擎、索引、字符集与数据类型对照。","status":"active","related":[{"title":"01 · 连接数据库与准备练习数据","link":"/middleware/mysql/base/mysql-crash-course-2/01-start","kind":"知识专题","scope":"general","audience":"general"},{"title":"02 · 检索、排序与条件过滤","link":"/middleware/mysql/base/mysql-crash-course-2/02-filtering","kind":"知识专题","scope":"general","audience":"general"},{"title":"03 · 计算、汇总与多表查询","link":"/middleware/mysql/base/mysql-crash-course-2/03-querying","kind":"知识专题","scope":"general","audience":"general"},{"title":"04 · 数据写入、表结构与视图","link":"/middleware/mysql/base/mysql-crash-course-2/04-tables","kind":"知识专题","scope":"general","audience":"general"},{"title":"05 · 存储程序与事务边界","link":"/middleware/mysql/base/mysql-crash-course-2/05-programming","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"MySQL 基础概念对照","link":"/middleware/mysql/plus/subjects/mysql-base"},"next":{"text":"MySQL 基础概念对照 · 字符集至其他类似的数据库","link":"/middleware/mysql/plus/subjects/mysql-base-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"MySQL 基础概念对照","link":"/middleware/mysql/plus/subjects/mysql-base"},"next":{"text":"MySQL 基础概念对照 · 字符集至其他类似的数据库","link":"/middleware/mysql/plus/subjects/mysql-base-part-02"}},"headers":[],"relativePath":"middleware/mysql/plus/subjects/mysql-base-part-01.md","filePath":"middleware/mysql/plus/subjects/mysql-base-part-01.md"}'),l={name:"middleware/mysql/plus/subjects/mysql-base-part-01.md"};function s(o,t,i,n,c,y){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="mysql-基础概念对照-·-mysql至索引" tabindex="-1">MySQL 基础概念对照 · MySQL至索引 <a class="header-anchor" href="#mysql-基础概念对照-·-mysql至索引" aria-label="Permalink to &quot;MySQL 基础概念对照 · MySQL至索引&quot;">​</a></h1><p><a href="/middleware/mysql/plus/subjects/mysql-base">返回分篇目录</a></p><h2 id="mysql-基础概念对照" tabindex="-1">MySQL 基础概念对照 <a class="header-anchor" href="#mysql-基础概念对照" aria-label="Permalink to &quot;MySQL 基础概念对照 {#mysql-基础概念对照}&quot;">​</a></h2><blockquote><p><strong>M4版本边界（2026-10-17）：</strong> 本页作为数据类型、引擎与术语广度对照保留；ACID和隔离性的简表不能理解为并发事务完全互不影响或提交即不需要备份。现行<a href="/middleware/mysql/base/advanced/transactions#isolation">事务快照与失败处理</a>和<a href="/middleware/mysql/plus/practice/application#run">完整应用</a>给出8.4.7实际验证路径。</p></blockquote><p><span id="mysql-base"></span></p><h2 id="mysql" tabindex="-1">MySQL <a class="header-anchor" href="#mysql" aria-label="Permalink to &quot;MySQL {#mysql}&quot;">​</a></h2><blockquote><p>MySQL 是一个开源的关系型数据库管理系统，广泛应用于 Web 应用程序的开发中。它提供了一个强大的、稳定的、高效的、可扩展的数据库解决方案，能够满足从小型网站到大型企业级应用的各种需求。</p></blockquote><ul><li>特点</li></ul><ol><li><strong>关系型数据库管理系统（RDBMS）</strong>：MySQL 是一种关系型数据库管理系统，它采用了关系模型来组织数据。数据存储在表中，表之间通过外键关联，形成了数据之间的关系。</li><li><strong>开源性</strong>：MySQL 是开源软件，可以免费获取和使用。这使得它成为许多开发者和企业的首选数据库解决方案之一。</li><li><strong>跨平台性</strong>：MySQL 可以在多种操作系统上运行，包括 Windows、Linux、Mac 等，因此具有很好的跨平台性。</li><li><strong>多用户支持</strong>：MySQL 支持多用户同时访问数据库，可以设置不同的权限和访问级别，确保数据的安全性和完整性。</li><li><strong>SQL（Structured Query Language）支持</strong>：MySQL 使用 SQL 作为操作数据库的标准语言。通过 SQL，用户可以执行各种操作，包括数据的查询、插入、更新、删除等。</li><li><strong>性能优化</strong>：MySQL 在设计和实现上对性能进行了优化，可以处理大规模的数据和高并发访问。它支持多种存储引擎，如 InnoDB、MyISAM 等，用户可以根据实际需求选择合适的存储引擎来优化性能。</li><li><strong>事务支持</strong>：MySQL 支持事务，保证了数据的一致性和可靠性。用户可以使用事务来批量执行操作，并在需要时进行回滚或提交。</li><li><strong>数据备份和恢复</strong>：MySQL 提供了备份和恢复数据库的工具和机制，可以定期备份数据库，以防止数据丢失或损坏，并在需要时进行数据恢复。</li><li><strong>可扩展性</strong>：MySQL 是一个可扩展的数据库系统，可以通过添加更多的服务器节点来扩展数据库的性能和容量。它支持主从复制、分区、分片等技术来实现数据库的水平和垂直扩展。</li><li><strong>社区支持和生态系统</strong>：MySQL 拥有庞大的用户社区和开发者社区，用户可以在社区中获取到丰富的资源、文档和支持。此外，MySQL 生态系统也非常丰富，有许多第三方工具和插件可以与 MySQL 集成，扩展其功能和应用场景。</li></ol><h2 id="事务" tabindex="-1">事务 <a class="header-anchor" href="#事务" aria-label="Permalink to &quot;事务 {#事务}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>描述</th></tr></thead><tbody><tr><td>原子性（Atomicity）</td><td>事务是一个不可分割的工作单位，要么全部执行成功，要么全部失败回滚。</td></tr><tr><td>一致性（Consistency）</td><td>事务执行前后数据库的完整性约束不会被破坏，即使事务执行失败也不会导致数据处于不一致的状态。</td></tr><tr><td>隔离性（Isolation）</td><td>隔离级别规定并发事务的可见性与相互影响；锁等待、快照和允许的读现象依级别及语句而异，见<a href="/middleware/mysql/base/advanced/transactions#isolation">事务快照</a>。</td></tr><tr><td>持久性（Durability）</td><td>提交后的恢复保证依赖引擎、日志刷盘配置与故障模型；持久性不代替备份，也不能抵御所有介质损坏。</td></tr></tbody></table><h2 id="关系型数据库" tabindex="-1">关系型数据库 <a class="header-anchor" href="#关系型数据库" aria-label="Permalink to &quot;关系型数据库 {#关系型数据库}&quot;">​</a></h2><blockquote><p>关系型数据库是一种结构化的数据库，它使用了关系模型来组织和管理数据。关系型数据库的核心概念是表、行和列，数据以表的形式存储，每个表由多行（记录）组成，每行包含了多个列（字段）。这种组织方式使得数据之间的关系变得清晰和易于管理。</p></blockquote><ol><li><strong>表（Table）</strong>：表是关系型数据库中的基本单位，用于存储特定类型的数据。每个表由一系列行和列组成，行代表记录，列代表字段。表可以有不同的列，每列具有特定的数据类型，如整数、字符、日期等。</li><li><strong>行（Row）</strong>：行也称为记录或元组，代表表中的一个实体或数据项。每行包含了一组相关的数据，每个字段对应一个数据值。行之间的顺序一般没有特定意义，可以通过主键来唯一标识和区分各行。</li><li><strong>列（Column）</strong>：列是表的结构化部分，用于定义每个记录的属性。每列具有特定的数据类型和约束，如整数、字符、日期、唯一性约束、非空约束等。列名通常用于标识和访问特定的数据项。</li><li><strong>主键（Primary Key）</strong>：主键是表中用于唯一标识每行记录的一列或一组列。主键必须是唯一的，且不能为空。通过主键可以快速定位和访问表中的特定记录，保证数据的完整性和一致性。</li><li><strong>外键（Foreign Key）</strong>：外键是表中的一列，它建立了与其他表之间的关联关系。外键用于指定一个表中的数据与另一个表中的数据之间的关系，通过外键可以实现表之间的引用完整性约束。</li><li><strong>关系（Relationship）</strong>：关系是指表之间的联系和连接。通过外键建立的关联关系可以帮助我们在多个表之间进行数据查询和操作，实现数据的关联和一致性。</li><li><strong>SQL（Structured Query Language）</strong>：SQL 是关系型数据库管理系统用于操作数据的标准语言。通过 SQL，用户可以执行各种操作，包括数据的查询、插入、更新、删除等，以及表的创建、修改、删除等管理操作。</li><li><strong>事务（Transaction）</strong>：事务是一系列数据库操作的集合，它要么全部执行成功，要么全部失败，具有原子性、一致性、隔离性和持久性（ACID 特性）。</li><li><strong>范式（Normalization）</strong>：范式是用于设计关系型数据库模式的一组规范化原则，旨在减少数据冗余和提高数据的存储效率。通过范式化设计，可以确保数据库的数据结构合理和标准化。</li></ol><h2 id="数据引擎" tabindex="-1">数据引擎 <a class="header-anchor" href="#数据引擎" aria-label="Permalink to &quot;数据引擎 {#数据引擎}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>存储引擎</th><th>特点</th><th>优点</th><th>缺点</th><th>适用场景</th></tr></thead><tbody><tr><td>InnoDB</td><td>支持事务、行级锁、外键约束</td><td>数据完整性强，支持高并发</td><td>内存消耗较大，性能相对较低</td><td>事务处理型应用，如电子商务平台、金融系统等</td></tr><tr><td>MyISAM</td><td>不支持事务、支持全表锁、查询性能较快</td><td>查询性能好，适用于读操作较多的场景</td><td>不支持事务、容易出现表级锁、不适合高并发写入</td><td>读操作较多、写操作较少的应用，如博客、新闻网站等</td></tr><tr><td>Memory</td><td>将数据存储在内存中，快速的数据访问速度</td><td>读写速度极快，适用于临时表和缓存数据</td><td>数据不持久化，服务器重启后数据丢失</td><td>临时表、缓存数据等需要快速访问的临时性数据存储</td></tr><tr><td>CSV</td><td>将数据存储在 CSV 文件中</td><td>适用于导入/导出数据到 CSV 文件</td><td>不支持事务、不支持索引、不适合大规模数据操作</td><td>导入/导出数据到 CSV 文件</td></tr><tr><td>Archive</td><td>高压缩比，适用于数据归档和备份等场景</td><td>压缩比高，适用于归档和备份数据</td><td>不支持事务、不支持索引、不适合频繁读写操作</td><td>数据归档、备份等场景</td></tr><tr><td>Blackhole</td><td>写入的数据被丢弃，适用于数据复制和转发</td><td>用于数据复制和转发</td><td>不保存数据，仅用于数据转发</td><td>数据复制、数据转发等场景</td></tr><tr><td>NDB Cluster</td><td>分布式存储和高可用性特性</td><td>提供高可用性和水平扩展能力，适用于分布式存储</td><td>配置和管理复杂，性能相对较低</td><td>需要高可用性和水平扩展能力的分布式存储场景</td></tr></tbody></table><h2 id="sql-语言" tabindex="-1">SQL 语言 <a class="header-anchor" href="#sql-语言" aria-label="Permalink to &quot;SQL 语言 {#sql-语言}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>简称</th><th>描述</th></tr></thead><tbody><tr><td>DDL (Data Definition Language)</td><td>定义</td><td>用于定义、修改和删除数据库对象（表、索引等）的语言。包括 <code>CREATE</code>、<code>ALTER</code>、<code>DROP</code> 等命令。</td></tr><tr><td>DML (Data Manipulation Language)</td><td>操作</td><td>用于对数据库中的数据进行操作的语言。包括 <code>INSERT</code>、<code>UPDATE</code>、<code>DELETE</code> 等命令。</td></tr><tr><td>DQL (Data Query Language)</td><td>查询</td><td>用于从数据库中检索数据的语言。主要命令是 <code>SELECT</code>。</td></tr><tr><td>DCL (Data Control Language)</td><td>控制</td><td>用于控制数据库访问权限和用户管理的语言。包括 <code>GRANT</code>、<code>REVOKE</code> 等命令。</td></tr><tr><td>TCL (Transaction Control Language)</td><td>事务</td><td>用于管理数据库事务的语言。包括 <code>COMMIT</code>、<code>ROLLBACK</code>、<code>SAVEPOINT</code> 等命令。</td></tr></tbody></table><h2 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引 {#索引}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>索引类型</th><th>特点</th><th>优势</th><th>劣势</th><th>适用场景</th></tr></thead><tbody><tr><td>B-Tree 索引</td><td>支持精确查找和范围查找，适用于大多数查询</td><td>支持范围查询、排序和分组等操作</td><td>查询的效率受数据量和索引列的数据分布影响</td><td>WHERE 子句中的条件查询，等值查询、范围查询等操作</td></tr><tr><td>哈希索引</td><td>适用于等值查询，具有快速的查找速度</td><td>查找速度快</td><td>不支持范围查询、排序和分组等操作</td><td>内存中的临时表和内存表</td></tr><tr><td>全文索引</td><td>用于全文搜索，支持文本内容的快速检索</td><td>支持对文本内容进行全文搜索和相关性排序</td><td>不适用于精确匹配和排序</td><td>需要进行全文搜索的场景，如博客、论坛等包含大量文本内容的应用</td></tr><tr><td>空间索引</td><td>用于对空间数据进行查询，支持空间对象的查询</td><td>支持距离查询、相交查询等空间操作</td><td>不适用于非空间数据</td><td>地图应用、位置服务等需要处理空间数据的应用场景</td></tr></tbody></table>',20)])])}const u=d(l,[["render",s]]);export{m as __pageData,u as default};
